data class FrameHeader(val length: Int, val type: Int, val flags: Int, val streamId: Int)

fun readHeader(b: ByteArray, at: Int): FrameHeader {
    fun u8(i: Int) = b[at + i].toInt() and 0xFF
    val length = (u8(0) shl 16) or (u8(1) shl 8) or u8(2)      // 24 bits
    val stream = ((u8(5) and 0x7F) shl 24) or (u8(6) shl 16) or (u8(7) shl 8) or u8(8)  // drop the reserved bit
    return FrameHeader(length, type = u8(3), flags = u8(4), streamId = stream)
}

// HTTP/1.1 sends one message at a time, so its position on the connection says which request it
// belongs to; HTTP/2 interleaves frames of many requests, so every frame must carry its stream's number.
